(459, 1, 10, 'hasCaptioning', 'hasCaptioning', 'Corresponds to \'fragment\' in the Ontology for Media Resources with a \'fragment.role\' meaning \"captioning\". This property can for example point to a spatial fragment, a VideoTrack or a DataTrack. The language of the captioning track can be expressed by attaching a \'hasLanguage\' property to the specific track.'),
(460, 1, 10, 'hasChapter', 'hasChapter', 'Corresponds to \'fragment\' in the Ontology for Media Resources with a \'fragment.role\' meaning \"chapter\".'),
(461, 1, 10, 'hasClassification', 'hasClassification', 'Corresponds to \'targetAudience.classification\' in the Ontology for Media Resources. This property is used to provide a value characterising the target audience.'),
(462, 1, 10, 'hasClassificationSystem', 'hasClassificationSystem', 'Corresponds to \'targetAudience.identifier\' in the Ontology for Media Resources. This is used to identify the reference sheme against which the target audience has been characterised.'),
(463, 1, 10, 'hasCompression', 'hasCompression', 'Corresponds to \'compression\' in the Ontology for Media Resources.'),
(464, 1, 10, 'hasContributedTo', 'hasContributedTo', NULL),
(465, 1, 10, 'hasContributor', 'hasContributor', 'Corresponds to \'contributor.contributor\' in the Ontology for Media Resources. Subproperties can be used to distinguish different values of \'contributor.role\'.'),
(466, 1, 10, 'hasCopyrightOver', 'hasCopyrightOver', NULL),
(467, 1, 10, 'hasCreated', 'hasCreated', NULL),
(468, 1, 10, 'hasCreator', 'hasCreator', 'Corresponds to \'creator.creator\' in the Ontology for Media Resources. Subproperties can be used to distinguish different values of \'creator.role\'. Note that this property is semantically a subproperty of \'hasContributor\'.'),
(469, 1, 10, 'hasFormat', 'hasFormat', 'Corresponds to \'format\' in the Ontology for Media Resources.'),
(470, 1, 10, 'hasFragment', 'hasFragment', 'Corresponds to \'fragment\' in the Ontology for Media Resources. Subproperties can be used to distinguish different values of \'fragment.role\'.'),
(471, 1, 10, 'hasGenre', 'hasGenre', 'Corresponds to \'genre\' in the Ontology for Media Resources.'),
(472, 1, 10, 'hasKeyword', 'hasKeyword', 'Corresponds to \'keyword\' in the Ontology for Media Resources.'),
(473, 1, 10, 'hasLanguage', 'hasLanguage', 'Corresponds to \'language\' in the Ontology for Media Resources. The language used in the resource. A controlled vocabulary such as defined in BCP 47 SHOULD be used. This property can also be used to identify the presence of sign language (RFC 5646). By inheritance, the hasLanguage property applies indifferently at the media resource / fragment / track levels.  Best practice recommends to use to best possible level of granularity fo describe the usage of language within a media resource including at fragment and track levels.'),
(474, 1, 10, 'hasLocationCoordinateSystem', 'hasLocationCoordinateSystem', 'Corresponds to \'location.coordinateSystem\' in the Ontology for Media Resources.'),
(475, 1, 10, 'hasMember', 'hasMember', NULL),
(476, 1, 10, 'hasNamedFragment', 'hasNamedFragment', 'Corresponds to \'namedFragment\' in the Ontology for Media Resources.');
